+  <title>Notification Preferences</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      --bg: #0b1020;
+      --panel: #121a31;
+      --panel-2: #18233e;
+      --text: #eef2ff;
+      --muted: #aeb8d6;
+      --border: rgba(255, 255, 255, 0.12);
+      --accent: #8b5cf6;
+      --accent-2: #a78bfa;
+      --focus: #f9a8d4;
+      --success: #5eead4;
+      --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    html, body {
+      margin: 0;
+      min-height: 100%;
+    }
+
+    body {
+      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      background:
+        radial-gradient(circle at top, rgba(139, 92, 246, 0.22), transparent 34%),
+        linear-gradient(180deg, #0b1020 0%, #090d18 100%);
+      color: var(--text);
+      line-height: 1.5;
+    }
+
+    main {
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 24px;
+    }
+
+    .card {
+      width: min(100%, 640px);
+      background: linear-gradient(180deg, rgba(24, 35, 62, 0.96), rgba(18, 26, 49, 0.96));
+      border: 1px solid var(--border);
+      border-radius: 24px;
+      box-shadow: var(--shadow);
+      padding: clamp(24px, 4vw, 40px);
+      backdrop-filter: blur(10px);
+    }
+
+    h1 {
+      margin: 0 0 8px;
+      font-size: clamp(1.75rem, 4vw, 2.5rem);
+      line-height: 1.1;
+    }
+
+    .lede {
+      margin: 0 0 28px;
+      color: var(--muted);
+      max-width: 58ch;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      padding: 22px;
+      border-radius: 20px;
+      border: 1px solid var(--border);
+      background: rgba(8, 12, 24, 0.28);
+    }
+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+      min-inline-size: 0;
+    }
+
+    legend {
+      padding: 0;
+      font-size: 1.15rem;
+      font-weight: 700;
+      margin-bottom: 8px;
+    }
+
+    .required {
+      color: var(--accent-2);
+      font-weight: 700;
+    }
+
+    .hint {
+      margin: 0 0 16px;
+      color: var(--muted);
+    }
+
+    .options {
+      display: grid;
+      gap: 12px;
+    }
+
+    .option {
+      display: flex;
+      align-items: center;
+      gap: 14px;
+      padding: 14px 16px;
+      border-radius: 16px;
+      border: 1px solid var(--border);
+      background: rgba(255, 255, 255, 0.03);
+      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
+      cursor: pointer;
+    }
+
+    .option:hover {
+      border-color: rgba(167, 139, 250, 0.5);
+      background: rgba(167, 139, 250, 0.08);
+      transform: translateY(-1px);
+    }
+
+    .option input {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0;
+      flex: 0 0 auto;
+      accent-color: var(--accent);
+    }
+
+    .option span {
+      font-size: 1rem;
+      font-weight: 600;
+    }
+
+    .option input:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+      border-radius: 999px;
+    }
+
+    .actions {
+      display: flex;
+      justify-content: flex-end;
+    }
+
+    button[type="submit"] {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 0.9rem 1.4rem;
+      font: inherit;
+      font-weight: 700;
+      color: #0b1020;
+      background: linear-gradient(135deg, #c4b5fd, #8b5cf6);
+      box-shadow: 0 10px 30px rgba(139, 92, 246, 0.35);
+      cursor: pointer;
+      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
+    }
+
+    button[type="submit"]:hover {
+      transform: translateY(-1px);
+      filter: brightness(1.04);
+    }
+
+    button[type="submit"]:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 4px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--success);
+      font-weight: 600;
+    }
+
+    @media (max-width: 520px) {
+      main {
+        padding: 16px;
+      }
+
+      .form-field {
+        padding: 18px;
+      }
+
+      .actions {
+        justify-content: stretch;
+      }
+
+      button[type="submit"] {
+        width: 100%;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card, .form-field, .option {
+        border: 1px solid CanvasText;
+      }
+
+      button[type="submit"] {
+        border: 1px solid ButtonText;
+        background: ButtonFace;
+        color: ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="card" aria-labelledby="page-title">
+      <h1 id="page-title">Notification preferences</h1>
+      <p class="lede">Choose how you want to hear from us.</p>
+
+      <form id="preferences-form" novalidate>
+        <div class="form-field">
+          <fieldset aria-describedby="notifications-help">
+            <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
+            <p class="hint" id="notifications-help">Select one option.</p>
+
+            <div class="options">
+              <label class="option" for="notification-email">
+                <input id="notification-email" type="radio" name="notification-method" value="Email" required>
+                <span>Email</span>
+              </label>
+
+              <label class="option" for="notification-sms">
+                <input id="notification-sms" type="radio" name="notification-method" value="SMS" required>
+                <span>SMS</span>
+              </label>
+
+              <label class="option" for="notification-push">
+                <input id="notification-push" type="radio" name="notification-method" value="Push Notifications" required>
+                <span>Push Notifications</span>
+              </label>
+            </div>
+          </fieldset>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Save preference</button>
+        </div>
+
+        <p class="status" id="form-status" role="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('preferences-form');
+    const status = document.getElementById('form-status');
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      if (!form.checkValidity()) {
+        form.reportValidity();
+        status.textContent = '';
+        return;
+      }
+
+      const selected = form.querySelector('input[name="notification-method"]:checked');
+      status.textContent = `Preference saved: ${selected.value}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
