  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a31;
      --panel-2: #18233e;
      --text: #eef2ff;
      --muted: #aeb8d6;
      --border: rgba(255, 255, 255, 0.12);
      --accent: #8b5cf6;
      --accent-2: #a78bfa;
      --focus: #f9a8d4;
      --success: #5eead4;
      --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      margin: 0;
      min-height: 100%;
    }

    body {
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(139, 92, 246, 0.22), transparent 34%),
        linear-gradient(180deg, #0b1020 0%, #090d18 100%);
      color: var(--text);
      line-height: 1.5;
    }

