<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main>
    <section class="card" id="main-content" aria-labelledby="page-title">
      <h1 id="page-title">Notification preferences</h1>
      <p class="lede">Choose how you want to hear from us.</p>

      <form id="preferences-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notifications-help">
            <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
            <p class="hint" id="notifications-help">Select one option.</p>

            <div class="options">
              <label class="option" for="notification-email">
                <input id="notification-email" type="radio" name="notification-method" value="Email" required>
                <span>Email</span>
              </label>

              <label class="option" for="notification-sms">
                <input id="notification-sms" type="radio" name="notification-method" value="SMS" required>
                <span>SMS</span>
              </label>

              <label class="option" for="notification-push">
                <input id="notification-push" type="radio" name="notification-method" value="Push Notifications" required>
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Save preference</button>
        </div>

        <p class="status" id="form-status" role="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('preferences-form');
    const status = document.getElementById('form-status');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      if (!form.checkValidity()) {
        form.reportValidity();
        status.textContent = '';
        return;
      }

      const selected = form.querySelector('input[name="notification-method"]:checked');
      status.textContent = `Preference saved: ${selected.value}.`;
    });
  </script>
</body>
</html>
